function mpvDwClose(apply){const from=MPV.dwFrom;if(apply&&MPV.dr){const k={sort:S.vf.sort};S.vf={...MPV.dr,...k};vfSave();MPV.page=1;MPV.qd=null;}MPV.dr=null;MPV.dw=null;render();mpdFocus(from||"#mpv-tf");}
function mpvDwRender(){const c=document.getElementById("mpv-dwc"),y=c?c.scrollTop:0;render();const c2=document.getElementById("mpv-dwc");if(c2)c2.scrollTop=y;}
const mpvH32=s=>{let h=0;for(const ch of String(s))h=(h*31+ch.charCodeAt(0))|0;return(h>>>0).toString(36);};
function mpvOpt(key,v,label,n,on,o={}){const id="mpvo-"+key+"-"+mpvH32(v);return`<div class="mpv-opt${o.sub?" sub"+o.sub:""}${!on&&n===0?" vide":""}"><button type="button" id="${id}" role="${o.radio?"radio":"checkbox"}" aria-checked="${on}" class="mpv-ob3" data-mpv-o="${esc(key)}:${esc(v)}" data-act="${act(()=>{const d=MPV.dr;if(o.radio)d[key]=on&&o.toggle?"":v;else d[key]=d[key].includes(v)?d[key].filter(z=>z!==v):[...d[key],v];if(o.after)o.after(d);mpvDwRender();})}"><span class="mpv-box${o.radio?" rd":""}" aria-hidden="true"></span><span class="mpv-ot">${esc(label)}${o.hint?`<small>${esc(o.hint)}</small>`:""}</span>${n!=null?`<span class="mpv-on">${n}</span>`:""}</button>${o.exp?`<button type="button" class="mpv-oexp" id="${id}-x" aria-expanded="${o.open}" aria-label="${o.open?"Masquer":"Afficher"} ${esc(o.expLab)}" data-act="${o.exp}">${mpvI("chev","mpv-car")}</button>`:""}</div>`;}
function mpvRad(key,opts,base,tous){const d=MPV.dr;return[["",tous||"Indifférent"],...opts].map(([v,l,h])=>mpvOpt(key,v,l,v===""?base.length:base.filter(e=>mpvF(key==="qual"||key==="ag"||key==="vis"||key==="ref"||key==="pub"?key:key,e.x,{...d,[key]:v})).length,d[key]===v,{radio:true,hint:h})).join("");}
function mpvInc(g,base,key,lab){const d=MPV.dr,nu=base.filter(e=>MPV_UNK[key](e.x)).length,on=d.inc.includes(g),act1=MPV_ON[key](d);
  return`<div class="mpv-inc${act1?"":" off"}" data-mpv-inc="${g}"><label><input type="checkbox" id="mpv-inc-${g}" ${on?"checked":""} ${act1?"":"disabled"} data-act="${act(()=>{d.inc=on?d.inc.filter(z=>z!==g):[...d.inc,g];mpvDwRender();})}"> Inclure aussi les fiches non renseignées (${lab})</label><small data-mpv-nu="${nu}">${nu} fiche${nu>1?"s":""} sans cette information dans le périmètre${act1?(on?" : incluses et signalées à part":" : exclues"):" · s'applique quand un choix est fait"}. Non renseigné ≠ « Non ».</small></div>`;}
function mpvLong(key,entries,limit,searchable,lab){const q=normV((MPV.ls||{})[key]||"").toLowerCase(),d=MPV.dr,all=(MPV.lsAll||{})[key];
  let e=q?entries.filter(([,l])=>normV(l).toLowerCase().includes(q)):entries;const sel=e.filter(([v])=>d[key].includes(v)),rest=e.filter(([v])=>!d[key].includes(v));e=[...sel,...rest];const show=all||q||e.length<=limit?e:e.slice(0,limit);
  return(searchable?`<div class="mpv-lsr">${mpvI("search","mpv-qi")}<label class="mpv-sr" for="mpv-ls-${key}">Rechercher : ${esc(lab)}</label><input id="mpv-ls-${key}" type="search" data-mpv-ls="${key}" placeholder="Rechercher ${esc(lab.toLowerCase())}…" value="${esc((MPV.ls||{})[key]||"")}"></div>`:"")+
    `<div class="mpv-ol">${show.map(([v,l,n])=>mpvOpt(key,v,l,n,d[key].includes(v))).join("")||`<p class="mpv-mut">Aucun résultat</p>`}</div>`+(!q&&e.length>limit?`<button type="button" class="mpv-lk" id="mpv-more-${key}" data-act="${act(()=>{MPV.lsAll=MPV.lsAll||{};MPV.lsAll[key]=!all;mpvDwRender();})}">${all?"Afficher moins":"Afficher les "+e.length}</button>`:"");}
function mpvSecH(k,extra){const s=MPV_SEC.find(z=>z[0]===k);return`<div class="mpv-sh2">${mpvI(s[2])}<h3>${esc(s[1])}</h3>${extra||""}</div>`;}
const MPV_TAG=`<span class="mpv-tag">Métadonnées PMMP</span>`,MPV_TAGE=`<span class="mpv-tag e">Règle EAIOS</span>`;
function mpvAcc(id,title,state,body){const o=!!(MPV.dwOpen||{})[id];return`<details class="mpv-acc" data-mpv-acc="${id}"${o?" open":""}><summary id="mpv-acc-${id}">${mpvI("chev","mpv-car")}<b>${esc(title)}</b><small>${state}</small></summary><div>${body}</div></details>`;}
document.getElementById("view").addEventListener("toggle",e=>{const t=e.target;if(t&&t.dataset&&t.dataset.mpvAcc){MPV.dwOpen=MPV.dwOpen||{};MPV.dwOpen[t.dataset.mpvAcc]=t.open;}},true);
function mpvDrawer(B){const d=MPV.dr,BD=k=>mpvBaseFor(B,d,k),nres=B.R.filter(e=>mpvM(e,d,null)).length,cat=S.cat,ND=cat.n_details,NN=cat.items.length;
  let c="";
  /* Recherche */
  c+=`<section id="mpv-s-rech" data-mpv-sec="rech" aria-labelledby="mpv-st-rech">${mpvSecH("rech")}<div class="mpv-two"><label class="mpv-fld">Mots-clés<input id="mpv-dq" type="search" data-mpv-di="q:trim" value="${esc(d.q)}" placeholder="Référence, objet, acheteur ou lieu…"></label><label class="mpv-fld">Mode<select id="mpv-dqm">${MPV_QM.map(([v,l])=>`<option value="${v}"${d.qmode===v?" selected":""}>${esc(l)}</option>`).join("")}</select></label></div>
    <p class="mpv-mut">Tous les mots : chaque mot présent (début de mot ; nombres exacts). Au moins un mot : un seul suffit. Expression exacte : mots contigus dans cet ordre. Référence exacte : segments entiers de la référence (75/CL/2026 ≠ 175/CL/2026). Porte sur la référence, l'objet, l'acheteur et les lieux affichés ; ce n'est pas le moteur de PMMP.</p>
    <div class="mpv-sv"><b>Mes recherches</b>${S.saved.length?`<ul>${S.saved.map((r,i)=>`<li><button type="button" class="mpv-lk" id="mpv-sv-${i}" data-act="${act(()=>{const v=mpvClone({...VF0,...r.vf});const w=mpvMigr(v);v.sort=d.sort;MPV.dr=v;if(w.length)MPV.migr=w;mpvDwRender();})}">${esc(r.nom)}</button> <small>charge dans le brouillon</small></li>`).join("")}</ul>`:`<p class="mpv-mut">Aucune recherche enregistrée.</p>`}
    ${editable()?`<div class="mpv-two"><label class="mpv-fld">Nom<input id="mpv-svn" type="text" value="${esc(MPV.svn||"")}" placeholder="ex. Travaux du Sud" data-mpv-di="__svn:raw"></label><button type="button" class="mpv-bs2" id="mpv-svb" data-act="${act(()=>{const n=String(d.__svn||MPV.svn||"").trim();if(!n)return toast("Donnez un nom à la recherche.");const vf=mpvClone(d);delete vf.sort;delete vf.__svn;S.saved=[...S.saved.filter(r=>r.nom!==n),{nom:n,vf}];saveSearches();delete d.__svn;mpvDwRender();toast("Recherche enregistrée (brouillon actuel).");})}">Enregistrer cette recherche</button></div><p class="mpv-mut">Enregistrement explicite, partagé entre vos appareils ; n'applique rien.</p>`:""}</div></section>`;
  /* Acheteur & procédure */
  {const EN=mpvCnt(BD("ents"),x=>x.ent?[x.ent]:[]),MO=mpvCnt(BD("mos"),x=>[x._mo]),PR=mpvCnt(BD("procs"),x=>[x.proc||"Procédure non indiquée"]);
   c+=`<section id="mpv-s-ach" data-mpv-sec="ach">${mpvSecH("ach",MPV_TAG)}<div class="mpv-two"><div><h4>Entité publique</h4>${mpvLong("ents",[...EN.entries()].sort((a,b)=>b[1]-a[1]).map(([v,n])=>[v,v,n]),6,true,"Entité publique")}</div><div><h4>Acheteur public</h4>${mpvLong("mos",[...MO.entries()].sort((a,b)=>b[1]-a[1]).map(([v,n])=>[v,v,n]),6,true,"Acheteur public")}</div></div>
   <div class="mpv-two"><label class="mpv-fld">Référence exacte<input id="mpv-dref" type="search" data-mpv-di="ref:trim" value="${esc(d.ref)}" placeholder="Saisir une référence…"><small>Segments entiers de la référence affichée.</small></label><div><h4>Procédure</h4>${mpvLong("procs",[...PR.entries()].sort((a,b)=>b[1]-a[1]).map(([v,n])=>[v,v,n]),6,false,"Procédure")}</div></div>
   <div class="mpv-dis" data-mpv-dis="mode"><b>Mode de passation</b><span>Non transmis au catalogue (seule la procédure l'est)</span><a class="mpv-lk" href="https://www.marchespublics.gov.ma/index.php5?page=entreprise.EntrepriseAdvancedSearch&searchAnnCons=" target="_blank" rel="noopener">Vérifier sur PMMP${mpvI("ext","mpv-ie")}</a></div>
   <div class="mpv-dis" data-mpv-dis="type"><b>Type d'acheteur (État, collectivité, établissement public)</b><span>Désactivé : classification ancienne, non vérifiable sur PMMP</span></div></section>`;}
  /* Localisation */
  {const R=mpvCnt(BD("regs"),x=>x._regs),Pv=mpvCnt(BD("provs"),x=>x.lx||[]),regs=[...Object.keys(cat.regions),...(B.R.some(e=>(e.x.etr||[]).length)?["Étranger"]:[])];
   c+=`<section id="mpv-s-loc" data-mpv-sec="loc">${mpvSecH("loc",MPV_TAG)}<p class="mpv-mut">Lieu d'exécution déclaré sur PMMP (pas l'adresse de l'acheteur). Une consultation sur plusieurs régions compte dans chacune.</p><div class="mpv-ol">${regs.map(r=>{const ps=cat.regions[r]||[],ok="r:"+r,open=!!(MPV.lsAll||{})[ok]||ps.some(p=>d.provs.includes(p[0]));
     return mpvOpt("regs",r,r,R.get(r)||0,d.regs.includes(r),{exp:ps.length?act(()=>{MPV.lsAll=MPV.lsAll||{};MPV.lsAll[ok]=!open;mpvDwRender();}):null,open,expLab:"les provinces de "+r,after:dd=>{dd.provs=dd.provs.filter(p=>!dd.regs.length||dd.regs.includes(PROV2REG[p]));}})+(open?ps.map(p=>mpvOpt("provs",p[0],nice(p[0]),Pv.get(p[0])||0,d.provs.includes(p[0]),{sub:1})).join(""):"");}).join("")}</div>
     <h4>Portée ${MPV_TAGE}</h4><div class="mpv-ol">${mpvRad("portee",[["loc","Marchés locaux"],["nat","Marchés nationaux","Plus de 6 provinces ou tout le Maroc : règle EAIOS, pas une catégorie PMMP"]],BD("portee"),"Toutes")}</div></section>`;}
  /* Catégories & domaines */
  {const C=mpvCnt(BD("cats"),x=>[x.cat]),bd=BD("doms"),D=mpvCnt(bd,x=>x._doms||[]),keys=[...D.keys()],q=normV((MPV.ls||{}).doms||"").toLowerCase();
   const kids=p=>keys.filter(z=>p?z.startsWith(p+" / ")&&z.split(" / ").length===p.split(" / ").length+1:!z.includes(" / ")).sort((a,b)=>(D.get(b)-D.get(a))||a.localeCompare(b));
   const row=(z,dep)=>{const ch=dep<3?kids(z):[],ex="d:"+z,open=!!(MPV.lsAll||{})[ex]||d.doms.some(s=>s.startsWith(z+" / "));return mpvOpt("doms",z,z.split(" / ").pop(),D.get(z)||0,d.doms.includes(z),{sub:dep>1?dep-1:0,exp:ch.length?act(()=>{MPV.lsAll=MPV.lsAll||{};MPV.lsAll[ex]=!open;mpvDwRender();}):null,open,expLab:"les sous-domaines de "+z.split(" / ").pop()})+(open?ch.map(cz=>row(cz,dep+1)).join(""):"");};
   c+=`<section id="mpv-s-cat" data-mpv-sec="cat">${mpvSecH("cat",MPV_TAG)}<h4>Catégorie principale</h4><div class="mpv-ol">${["Travaux","Fournitures","Services"].map(z=>mpvOpt("cats",z,z,C.get(z)||0,d.cats.includes(z))).join("")}</div>
   <h4>Domaines d'activité (arborescence PMMP, 3 niveaux, plusieurs choix)</h4><div class="mpv-lsr">${mpvI("search","mpv-qi")}<label class="mpv-sr" for="mpv-ls-doms">Rechercher un domaine</label><input id="mpv-ls-doms" type="search" data-mpv-ls="doms" placeholder="Rechercher un domaine…" value="${esc((MPV.ls||{}).doms||"")}"></div>
   <div class="mpv-ol">${q?keys.filter(z=>normV(z).toLowerCase().includes(q)).sort((a,b)=>D.get(b)-D.get(a)).slice(0,40).map(z=>mpvOpt("doms",z,z,D.get(z)||0,d.doms.includes(z))).join("")||`<p class="mpv-mut">Aucun domaine</p>`:kids("").map(z=>row(z,1)).join("")}</div>${mpvInc("doms",bd,"doms","domaine")}</section>`;}
  /* Dates */
  c+=`<section id="mpv-s-dates" data-mpv-sec="dates">${mpvSecH("dates",MPV_TAG)}<p class="mpv-mut">Jours et heures du Maroc. Sans heure indiquée, une clôture du jour reste ouverte jusqu'à la fin du jour.</p><div class="mpv-two"><div><h4>Date limite de remise des plis</h4><div class="mpv-ol">${mpvRad("lim",LIMS.map(([v,l])=>[v,v==="plus"?"Dans plus de 30 jours":"Dans les "+l]),BD("lim"),"Toutes les dates")}</div>
   <div class="mpv-two"><label class="mpv-fld">Du<input id="mpv-dlf" type="date" data-mpv-di="limFrom:raw" value="${esc(d.limFrom)}"></label><label class="mpv-fld">Au<input id="mpv-dlt" type="date" data-mpv-di="limTo:raw" value="${esc(d.limTo)}"></label></div></div>
   <div><h4>Date de mise en ligne</h4><div class="mpv-ol">${mpvRad("pub",PUBS.map(([v,l])=>[v,"Depuis "+l]),BD("pub"),"Toutes")}</div><div class="mpv-two"><label class="mpv-fld">Du<input id="mpv-dpf" type="date" data-mpv-di="pubFrom:raw" value="${esc(d.pubFrom)}"></label><label class="mpv-fld">Au<input id="mpv-dpt" type="date" data-mpv-di="pubTo:raw" value="${esc(d.pubTo)}"></label></div></div></div></section>`;
  /* Montants */
  {const bm=BD("mts"),bc=BD("cau");c+=`<section id="mpv-s-mts" data-mpv-sec="mts">${mpvSecH("mts",MPV_TAG)}<div class="mpv-two"><div><h4>Estimation du maître d'ouvrage (TTC)</h4><div class="mpv-ol">${MTS.map(([v,l])=>mpvOpt("mts",v,v==="np"?l:l+" DH",bm.filter(e=>FACETS.mts(e.x,{...d,mts:[v],estMin:"",estMax:""})).length,d.mts.includes(v))).join("")}</div>
    <div class="mpv-two"><label class="mpv-fld">Minimum (M DH)<input id="mpv-emin" type="number" min="0" step="0.1" inputmode="decimal" data-mpv-di="estMin:raw" value="${esc(d.estMin)}"></label><label class="mpv-fld">Maximum (M DH)<input id="mpv-emax" type="number" min="0" step="0.1" inputmode="decimal" data-mpv-di="estMax:raw" value="${esc(d.estMax)}"></label></div>${d.estMin!==""&&d.estMax!==""&&+d.estMin>+d.estMax?`<p class="mpv-w" role="alert">Le minimum est supérieur au maximum : aucune annonce ne peut correspondre.</p>`:""}${mpvInc("mts",bm,"mts","estimation inconnue, y compris indiquée par lot")}</div>
    <div><h4>Caution provisoire</h4><div class="mpv-ol">${mpvRad("cau",[["le50","Jusqu'à 50 000 DH"],["le200","Jusqu'à 200 000 DH"],["gt200","Plus de 200 000 DH"],["zero","0 DH selon PMMP","À vérifier dans le DCE"],["np","Non indiquée sur PMMP","Fiche lue sans caution"]],bc,"Indifférent")}</div>${mpvInc("cau",bc,"cau","caution inconnue")}</div></div><p class="mpv-mut">Aucune somme TTC/HT n'est calculée ; une estimation inconnue n'est jamais 0.</p></section>`;}
  /* Conditions PMMP */
  {const bq=BD("qh"),Qs=new Map(),Sc=new Map(),Qq=new Map(),Cl=new Map();
   bq.forEach(e=>{const seen={s:new Set(),c:new Set(),q:new Set(),y:new Set()};(e.x.q||[]).forEach(q=>{const m=q.m||"",ks=m+"|"+q.s,kq=ks+"|"+(q.q||""),kc=m+"|"+(q.c||"");mpvSectL[ks]=q.sl||"";
     if(!seen.y.has(m)){seen.y.add(m);Qs.set(m,(Qs.get(m)||0)+1);}if((!d.qsys.length||d.qsys.includes(m))&&!seen.s.has(ks)){seen.s.add(ks);Sc.set(ks,{n:((Sc.get(ks)||{}).n||0)+1,m,s:q.s,sl:q.sl});}
     if((!d.qsys.length||d.qsys.includes(m))&&(!d.sects.length||d.sects.includes(ks))&&!seen.q.has(kq)){seen.q.add(kq);Qq.set(kq,{n:((Qq.get(kq)||{}).n||0)+1,t:q.q||"Qualification non nommée"});}
     if((!d.qsys.length||d.qsys.includes(m))&&!seen.c.has(kc)){seen.c.add(kc);Cl.set(kc,{n:((Cl.get(kc)||{}).n||0)+1,m,c:q.c});}});});
   const qb=`<p class="mpv-mut">Qualification exigée par l'annonce (pas celle d'une société). Les niveaux sont reliés : une annonce correspond si UNE même ligne de qualification satisfait système, secteur, qualification et classe choisis. Aucune comparaison de classes entre systèmes.</p>
     <div class="mpv-ol">${mpvRad("qual",[["sans","Non indiquée sur PMMP"],["avec","Indiquée sur PMMP"]],BD("qual"),"Indifférent")}</div>
     <h4>Système</h4><div class="mpv-ol">${[...Qs.entries()].sort((a,b)=>b[1]-a[1]).map(([m,n])=>mpvOpt("qsys",m,mpvSys(m),n,d.qsys.includes(m))).join("")||`<p class="mpv-mut">Aucune</p>`}</div>
     <h4>Secteur</h4>${mpvLong("sects",[...Sc.entries()].sort((a,b)=>b[1].n-a[1].n).map(([k,o])=>[k,mpvSys(o.m)+" · "+mpvSect(o.m,o.s,o.sl),o.n]),8,true,"Secteur")}
     <h4>Qualification</h4>${mpvLong("qqual",[...Qq.entries()].sort((a,b)=>b[1].n-a[1].n).map(([k,o])=>[k,o.t,o.n]),6,true,"Qualification")}
     <h4>Classe (par système)</h4><div class="mpv-ol">${[...Cl.entries()].sort((a,b)=>a[0].localeCompare(b[0])).map(([k,o])=>mpvOpt("qcls",k,mpvSys(o.m)+" · "+mpvCls(o.c),o.n,d.qcls.includes(k))).join("")||`<p class="mpv-mut">Aucune</p>`}</div>${mpvInc("qual",BD("qual"),"qual","qualification")}`;
   const st=(k,n)=>`${n} fiche${n>1?"s":""} sans détail · non renseigné ≠ non exigé`;const nu=B.R.filter(e=>!e.x.det).length;
   c+=`<section id="mpv-s-cond" data-mpv-sec="cond">${mpvSecH("cond",MPV_TAG)}${mpvAcc("qual","Qualification & classification",st("q",nu),qb)}
     ${mpvAcc("ag","Agréments",st("a",nu),`<div class="mpv-ol">${mpvRad("ag",[["sans","Non indiqué sur PMMP"],["avec","Demandé"]],BD("ag"))}</div>${mpvInc("ag",BD("ag"),"ag","agrément")}`)}
     ${mpvAcc("tp","Réservation TPE / PME",`${B.R.filter(e=>e.x.tp==null).length} fiches sans indication (non lues ou par lot)`,`<div class="mpv-ol">${mpvRad("tp",[["oui","Réservées TPE / PME"],["non","Non réservées"]],BD("tp"))}</div>${mpvInc("tp",BD("tp"),"tp","TPE/PME")}`)}
     ${mpvAcc("vis","Visite des lieux",st("v",nu),`<div class="mpv-ol">${mpvRad("vis",[["oui","Prévue"],["non","Non indiquée"]],BD("vis"))}</div>${mpvInc("vis",BD("vis"),"vis","visite")}`)}
     ${mpvAcc("lots","Allotissement","indiqué sur la liste PMMP",`<div class="mpv-ol">${mpvRad("lots",[["oui","Allotie"],["non","Non allotie selon PMMP"]],BD("lots"))}</div>`)}
     ${mpvAcc("env","Considérations environnementales","signalées sur la liste PMMP",`<div class="mpv-ol">${mpvRad("env",[["oui","Signalées"],["non","Non signalées"]],BD("env"))}</div>`)}
     <p class="mpv-warn2">${mpvI("warn")}Certains critères nécessitent une fiche détaillée (${ND} lues sur ${NN}). Pour chacun, « Inclure aussi les fiches non renseignées » les ajoute et les signale à part.</p></section>`;}
  /* Suivi & DCE */
  c+=`<section id="mpv-s-suiv" data-mpv-sec="suiv">${mpvSecH("suiv")}<h4>Suivi</h4><div class="mpv-ol">${mpvRad("suivi",[["oui","Suivies (dossier ouvert)"],["non","Non suivies"]],BD("suivi"),"Toutes")}</div><h4>DCE des consultations suivies</h4><div class="mpv-ol">${mpvRad("dce",[["joint","DCE joint au dossier"],["non","DCE pas encore joint"]],BD("dce"))}</div><p class="mpv-mut">Suivre ≠ participer. « DCE joint » seulement quand un fichier est au dossier.</p></section>`;
  /* Disponibilité */
  {const R2=B.R,u=k=>R2.filter(e=>MPV_UNK[k](e.x)).length;
   c+=`<section id="mpv-s-dispo" data-mpv-sec="dispo">${mpvSecH("dispo")}<ul class="mpv-dl2"><li><b>${ND}</b> fiches détaillées lues sur <b>${NN}</b> consultations du catalogue.</li><li>Sans qualification / agrément / visite connus : ${u("qual")} · TPE/PME inconnue : ${u("tp")} · estimation inconnue : ${u("mts")} · caution inconnue : ${u("cau")} · domaine inconnu : ${u("doms")}.</li></ul>
   <h4>Non disponible dans ce catalogue</h4><ul class="mpv-dl2"><li><b>Type d'annonce</b> : annonces de consultation uniquement (information, résultats, PV… non collectés).</li><li><b>Mode de passation</b> : non transmis au catalogue ; seule la procédure l'est.</li><li><b>Type d'acheteur</b> : classification ancienne non vérifiable, filtre désactivé.</li><li><b>Date de lecture de chaque fiche</b> : visible dans la fiche (provenance) quand elle est connue.</li></ul><p class="mpv-mut">Filtres inspirés de la recherche avancée PMMP, appliqués au catalogue collecté : les résultats peuvent différer de ceux du portail.</p></section>`;}
  const nav=MPV_SEC.map(([k,l,i])=>`<button type="button" data-mpv-dnav="${k}" id="mpv-dn-${k}" aria-current="${MPV.dw===k?"true":"false"}" data-act="${act(()=>{MPV.dw=k;mpvDwRender();const s=document.getElementById("mpv-s-"+k),cc=document.getElementById("mpv-dwc");if(s&&cc)cc.scrollTop=s.offsetTop-cc.offsetTop;mpdFocus('[data-mpv-dnav="'+k+'"]');})}">${mpvI(i)}<span>${esc(l)}</span></button>`).join("");
  return`<div class="mpv-dw" data-mpv-dw="1"><div class="mpv-dwbg" data-act="${act(()=>mpvDwClose(false))}"></div><div class="mpv-dwp" role="dialog" aria-modal="true" aria-labelledby="mpv-dwt"><header class="mpv-dwh"><span class="mpv-dwi">${mpvI("db")}</span><div><h2 id="mpv-dwt">Tous les filtres</h2><p>Recherche sur le catalogue collecté · disponibilité indiquée par critère · brouillon non appliqué</p></div><button type="button" class="mpv-dwx" id="mpv-dwx" aria-label="Fermer sans appliquer" data-act="${act(()=>mpvDwClose(false))}">${mpvI("x")}</button></header>
   <div class="mpv-dwm"><nav class="mpv-dwn" aria-label="Sections des filtres">${nav}</nav><div class="mpv-dwc" id="mpv-dwc">${c}</div></div>
   <footer class="mpv-dwf"><button type="button" class="mpv-bs2" id="mpv-dwr" data-act="${act(()=>{const k={sort:d.sort,etat:"ouv",suivi:"",pert:false};MPV.dr={...mpvClone(VF0),...k};mpvDwRender();})}">Réinitialiser</button><span class="mpv-mut" data-mpv-dwn="${nres}" role="status">${nres} consultation${nres>1?"s":""} avec ce brouillon</span><button type="button" class="mpv-bs2" id="mpv-dwa" data-act="${act(()=>mpvDwClose(false))}">Annuler</button><button type="button" class="mpv-bp" id="mpv-dwok" data-act="${act(()=>mpvDwClose(true))}">Appliquer les filtres</button></footer></div></div>`;}
document.addEventListener("keydown",e=>{if(!MPV.dr||!document.querySelector(".mpv-dwp"))return;
  if(e.key==="Escape"){e.preventDefault();e.stopPropagation();mpvDwClose(false);return;}
  if(e.key==="Tab"){const P=document.querySelector(".mpv-dwp"),F=[...P.querySelectorAll('button:not([disabled]),input:not([disabled]),select,a[href],summary,[tabindex]:not([tabindex="-1"])')].filter(x=>x.offsetParent!==null);if(!F.length)return;const a=F[0],z=F[F.length-1];
    if(!P.contains(document.activeElement)){e.preventDefault();a.focus();return;}if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus();}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus();}}},true);
/* ---- liste (remplace mpvCons) ---- */
function mpvCons(B,dm){const f=S.vf;S._fm=followedMap();
  if(!B)return`<div class="mpv-vide" data-mpv-etat="${S.catState}">${S.catState==="absent"?"Catalogue PMMP indisponible dans cette version : liste des consultations non affichée. Les consultations suivies restent dans l'onglet « Suivies ».":"Chargement du catalogue national…"}</div>`;
  const M=B.R.map(e=>[e,mpvMatch(e,f,null)]).filter(([,r])=>r.ok),list=M.map(([e])=>e).sort(mpvSortFn(f.sort)),nu=M.filter(([,r])=>r.unk).length,n=list.length,lk=JSON.stringify([f.q,f.q?f.qmode:"",f.etat,f.suivi,f.pert,mpvActive(f),f.sort]);
  if(lk!==MPV.lk){if(MPV.lk!==null)MPV.page=1;MPV.lk=lk;}const pages=Math.max(1,Math.ceil(n/MPV.per));MPV.page=Math.min(Math.max(1,MPV.page),pages);const i0=(MPV.page-1)*MPV.per,rows=list.slice(i0,i0+MPV.per);
  if(!MPV.sel||!B.by.get(MPV.sel))MPV.sel=rows[0]?rows[0].k:null;const inList=list.some(e=>e.k===MPV.sel);MPV.n=n;
  let h=mpvBar(B,n,nu);if(MPV.dr)h+=mpvDrawer(B);
  const scl=f.etat==="clos"?"clôturées":f.etat==="tout"?"ouvertes et clôturées":"ouvertes";
  h+=`<div class="mpv-grid" data-mob="${MPV.mob}"><section class="mpv-lst" aria-labelledby="mpv-lt"><div class="mpv-lh"><h2 id="mpv-lt" tabindex="-1">${n} consultation${n>1?"s":""} <small>${esc(scl)}${f.pert?", pertinentes":""}${f.suivi==="non"?", non suivies":f.suivi==="oui"?", suivies":""}${nu?` · dont <span data-mpv-nu-list="${nu}">${nu}</span> fiche${nu>1?"s":""} non renseignée${nu>1?"s":""} incluse${nu>1?"s":""}`:""}</small></h2><span class="mpv-mut" data-mpv-rng="${n?i0+1:0}-${i0+rows.length}/${n}">${n?(i0+1)+" – "+(i0+rows.length)+" sur "+n:"0 résultat"}</span></div>`;
  h+=n?`<ul class="mpv-rows">${rows.map(e=>mpvRow(e,dm,e.k===MPV.sel)).join("")}</ul>`:`<p class="mpv-vide" data-mpv-vide="1">Aucune consultation ne correspond${mpvActive(f).length||f.q?" : retirez un filtre ou changez le mode de recherche":""}.</p>`;
  if(pages>1){const W=[];for(let p=Math.max(1,MPV.page-2);p<=Math.min(pages,MPV.page+2);p++)W.push(p);
    h+=`<nav class="mpv-pg" aria-label="Pages de résultats"><button type="button" data-mpv-page="prev" ${MPV.page<=1?"disabled":""} data-act="${act(()=>{MPV.page--;render();mpdFocus("#mpv-lt");})}">‹ Précédent</button>${W[0]>1?`<button type="button" data-mpv-page="1" data-act="${act(()=>{MPV.page=1;render();mpdFocus("#mpv-lt");})}">1</button>${W[0]>2?"<span>…</span>":""}`:""}${W.map(p=>`<button type="button" data-mpv-page="${p}" ${p===MPV.page?'aria-current="page"':""} data-act="${act(()=>{MPV.page=p;render();mpdFocus("#mpv-lt");})}">${p}</button>`).join("")}${W[W.length-1]<pages?`${W[W.length-1]<pages-1?"<span>…</span>":""}<button type="button" data-mpv-page="${pages}" data-act="${act(()=>{MPV.page=pages;render();mpdFocus("#mpv-lt");})}">${pages}</button>`:""}<button type="button" data-mpv-page="next" ${MPV.page>=pages?"disabled":""} data-act="${act(()=>{MPV.page++;render();mpdFocus("#mpv-lt");})}">Suivant ›</button></nav>`;}
  h+=`<p class="mpv-note">${mpvI("info")}Clôturées : axe État ; dossiers suivis hors catalogue : onglet « Suivies ». La fiche sélectionnée reste affichée même hors page ou hors filtre.</p></section>${mpvPanel(B,dm,inList)}</div>`;
  return h;}
/* indicateurs : périmètre catalogue global (hors filtres) ; clic = axes et filtres correspondants, autres filtres retirés (annoncé) */
function mpvKpi(k){if(k==="dce"){MPV.tab="dce";MPN.outil="f:dce";}else{const keep={sort:S.vf.sort};S.vf={...mpvClone(VF0),...keep,etat:"ouv",pert:k==="pour",lim:k==="sept"?"7":""};MPV.tab="cons";MPN.outil="veille";MPV.page=1;vfSave();toast("Affichage : "+({ouv:"consultations ouvertes",pour:"pertinentes pour le groupe",sept:"clôture sous 7 jours"}[k])+" (autres filtres retirés).");}
  render();mpdFocus(k==="dce"?'[data-mpv-tab="dce"]':"#mpv-lt");}
function mpvTabs(){const T=[["cons","Consultations",MPV.n],["dce","DCE à récupérer",MPV.nDce],["suiv","Suivies",MPV.nSuiv]];
  return`<div class="mpv-tabs" role="tablist" aria-label="Vues du bureau B1.1">${T.map(([k,l,n])=>`<button type="button" role="tab" id="mpv-tab-${k}" data-mpv-tab="${k}" aria-selected="${MPV.tab===k}" tabindex="${MPV.tab===k?0:-1}" aria-controls="mpv-tp" data-act="${act(()=>{MPV.tab=k;MPN.outil=k==="dce"?"f:dce":"veille";MPV.conf=null;render();mpdFocus('[data-mpv-tab="'+k+'"]');})}">${esc(l)}${n!=null?` <span class="mpv-tn">(${n})</span>`:""}</button>`).join("")}</div>`;}
function mpvPage(){mpvCss();mpv2Css();if(MPN.outil!==MPV.outil){MPV.tab=MPN.outil==="f:dce"?"dce":MPV.tab==="suiv"?"suiv":"cons";MPV.outil=MPN.outil;}
  let B=null;if(S.cat){try{B=mpvBase();}catch(e){console.error(e);}}
  const now=Date.now(),G=S.aoState==="ok"?mpvDceGroupes(now):{O:[],E:[]},dm=mpvDosMap();MPV.nDce=S.aoState==="ok"?G.O.length:null;
  MPV.nSuiv=S.aoState==="ok"?Object.values(S.ao||{}).filter(a=>a&&(a.portail||a.veille)&&mpvOuvertDos(a,now)).length:null;
  const body=MPV.tab==="dce"?mpvDceTab(G):MPV.tab==="suiv"?mpvSuivTab(B):mpvCons(B,dm);if(MPV.tab!=="cons")MPV.n=B?B.R.filter(e=>mpvM(e,S.vf,null)).length:null;
  return`<div class="mpv" data-mpv="${MPV.v}" data-mpv-tab-on="${MPV.tab}">${mpvTop()}${mpvKpis(B,G).replace('<div class="mpv-kpis">','<div class="mpv-kpis" aria-label="Indicateurs du catalogue global, hors filtres">')}${mpvTabs()}<div id="mpv-tp" role="tabpanel" aria-labelledby="mpv-tab-${MPV.tab}">${body}</div></div>`;}
