function mpv2Css(){if(document.getElementById("mpv2-css"))return;const s=document.createElement("style");s.id="mpv2-css";s.textContent=MPV2_CSS+`@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .mpv{${MPV2_TOK}}}`;document.head.appendChild(s);}
